 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, color, texture, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, CircleGeometry, DoubleSide, SRGBColorSpace } = THREE;

  const visual = config.intent?.visualSpec ?? {};
  const colors = visual.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const items = config.textContent ?? visual.textContent ?? [];
  const primitiveEntries = config.cinematicPrimitives ?? visual.cinematicPrimitives ?? [];

  const ink = color(colors.ink);
  const surface = color(colors.surface);
  const paper = colors.paper;
  const accent = color(colors.accent);

  const root = new Group();
  root.name = config.id ?? 'features-card-2-label';

  const disposables = { geoms: [], mats: [], texs: [], timelines: [] };
  const primCleanups = [];

  // --- gradient card surface (engineered vertical gradient + subtle grain) ---
  const uvNode = uv();
  const noise = fract(
    sin(uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233))).mul(43758.5453)
  );
  const grain = noise.sub(0.5).mul(0.035);
  const gradient = mix(surface, ink, smoothstep(0, 1, uvNode.y)).add(grain);

  const cardW = 1.4;
  const cardH = 0.9;

  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  cardMat.colorNode = gradient;

  const card = new Mesh(cardGeo, cardMat);
  card.name = 'card-surface';
  root.add(card);
  disposables.geoms.push(cardGeo);
  disposables.mats.push(cardMat);

  // --- icon plane (orb-decor.png) ---
  const iconW = 0.6;
  const iconH = 0.6 * (320 / 512);
  const iconGeo = new PlaneGeometry(iconW, iconH);
  const iconMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });
  iconMat.colorNode = color(paper);

  const icon = new Mesh(iconGeo, iconMat);
  icon.position.set(0, 0.12, 0.015);
  icon.name = 'icon';
  root.add(icon);
  disposables.geoms.push(iconGeo);
  disposables.mats.push(iconMat);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = SRGBColorSpace;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        iconMat.colorNode = texture(tex, uv());
        iconMat.needsUpdate = true;
        disposables.texs.push(tex);
      })
      .catch(() => {
        // leave fallback paper fill
      });
  }

  // --- accent indicator ---
  const dotGeo = new CircleGeometry(0.045, 32);
  const dotMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });
  dotMat.colorNode = accent;

  const dot = new Mesh(dotGeo, dotMat);
  dot.position.set(cardW * 0.36, cardH * 0.36, 0.02);
  dot.name = 'accent-dot';
  root.add(dot);
  disposables.geoms.push(dotGeo);
  disposables.mats.push(dotMat);

  // --- text headline ---
  const headlineItem = items.find((i) => (i.role ?? 'headline') === 'headline') || items[0];
  if (headlineItem && headlineItem.text) {
    const textObj = ctx.fontAtlas.createText(String(headlineItem.text), {
      fontSize: headlineItem.typography?.fontSize ?? 39,
      color: paper,
      align: 'center',
      letterSpacingPx: 0.5,
    });
    textObj.position.set(0, -0.3, 0.03);
    textObj.name = 'headline';
    root.add(textObj);
  }

  // --- cinematic primitives ---
  for (const primitive of primitiveEntries) {
    if (!primitive?.name) continue;
    const factory = ctx.primitives?.[primitive.name];
    if (typeof factory !== 'function') continue;
    const result = factory(root, primitive.params ?? {});
    if (result?.timeline) disposables.timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') primCleanups.push(result.cleanup);
  }

  // --- handlers ---
  root.userData.handlers = {};

  // --- cleanup ---
  root.userData.cleanup = () => {
    disposables.timelines.forEach((tl) => {
      try { tl.kill(); } catch {}
    });
    primCleanups.forEach((fn) => {
      try { fn(); } catch {}
    });
    disposables.geoms.forEach((g) => g.dispose());
    disposables.mats.forEach((m) => m.dispose());
    disposables.texs.forEach((t) => t.dispose());
  };

  return root;
}
